<div class="card p-3"><table class="table table-hover dt"><thead><tr><th>Kode</th><th>Travel</th><th>Rekening</th><th>Nominal</th><th>Status</th><th>Diajukan</th><th>Tindakan</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r->payout_code) ?></td><td><?= e($r->partner_name) ?></td><td><?= e($r->bank_name_snapshot) ?> <?= e($r->account_number_snapshot) ?><br><small><?= e($r->account_holder_snapshot) ?></small></td><td><?= rupiah($r->net_amount) ?></td><td><?= badge($r->status) ?></td><td><?= fdt($r->created_at) ?></td>
<td><?php if ($r->status === 'requested'): ?><?= post_btn('admin/finance/payout_action/' . $r->id, 'Setujui', 'btn-success', ['action' => 'approve']) ?> <?= post_note('admin/finance/payout_action/' . $r->id, 'Tolak', 'btn-outline-danger', ['action' => 'reject']) ?>
<?php elseif ($r->status === 'approved'): ?><form method="post" enctype="multipart/form-data" action="<?= site_url('admin/finance/payout_action/' . $r->id) ?>" class="d-inline-flex gap-1"><?= csrf_field() ?><input type="hidden" name="action" value="paid"><input type="file" name="proof" class="form-control form-control-sm" style="width:170px"><button class="btn btn-sm btn-primary">Tandai Dibayar</button></form>
<?php elseif ($r->transfer_proof_path): ?><a target="_blank" href="<?= site_url('admin/files/payout_proof/' . $r->id) ?>">Bukti</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
